import { TweenLite } from 'gsap';
import { Container, Graphics, FederatedPointerEvent, PointData, Sprite, Texture } from 'pixi.js';

import { Slide } from './base-slide';
import { SliderControl } from './slider-control';

export interface ISliderFeatures {
    transitionTimes: { manual: number, auto: number };
    swipeTransition: { enabled: boolean };
    controlsTextures?: { enabled: Texture, disabled: Texture };
    autoTransition?: { slideChangeTime: number };
}

export class SlideManager extends Container {
    protected slides: Slide[];
    protected currentSlideIndex: number;
    protected slideMask: Graphics;
    protected slideOutPosition: number = 0;
    protected slideInPosition: number = 0;
    protected slideInTween!: TweenLite;
    protected slideOutTween!: TweenLite;

    protected controls: Container | undefined;
    protected controlsTextures: { enabled: Texture, disabled: Texture } | undefined;

    protected swipeRegion: Sprite | undefined;
    protected swipeThreshold: number;
    private interactionData: FederatedPointerEvent | null;

    private autoTransitionDurationS: number;
    private transitionDurationS: number;

    private timeBetweenAutoTransitionsMS: number | undefined;
    private autoTransitionTimeout: number = 0;
    private moveOffset: number = 0;

    private readonly defaultFeatures: ISliderFeatures = {
        transitionTimes: { manual: 0.5, auto: 1.5 },
        swipeTransition: { enabled: true },
        autoTransition: { slideChangeTime: 5000 }
    };

    constructor(slides: Slide[], features: Partial<ISliderFeatures> = {}, shouldAddChildren: boolean = true) {
        super();

        const combinedFeatures: ISliderFeatures = { ...this.defaultFeatures, ...features };

        this.slides = slides;

        this.currentSlideIndex = 0;
        this.autoTransitionDurationS = combinedFeatures.transitionTimes.auto;
        this.transitionDurationS = combinedFeatures.transitionTimes.manual;
        this.controlsTextures = combinedFeatures.controlsTextures;

        this.swipeThreshold = 100;
        this.interactionData = null;

        this.slideMask = new Graphics();
        this.slideMask.renderable = false;
        this.slides.forEach((slide) => { slide.mask = this.slideMask; });
        this.addChild(this.slideMask);

        this.onPointerDown = this.onPointerDown.bind(this);
        this.onPointerMove = this.onPointerMove.bind(this);
        this.onPointerUp = this.onPointerUp.bind(this);
        this.transitionSlideLeft = this.transitionSlideLeft.bind(this);
        this.transitionSlideRight = this.transitionSlideRight.bind(this);
        this.transitionSlideIn = this.transitionSlideIn.bind(this);
        this.goToSlideAt = this.goToSlideAt.bind(this);

        if (combinedFeatures.swipeTransition.enabled) {
            this.swipeRegion = new Sprite(Texture.WHITE);
            this.swipeRegion.interactive = true;
            this.swipeRegion.anchor.set(0.5);
            this.swipeRegion.alpha = 0.001;
            this.interactive = true;
            this.swipeRegion.on('pointerdown', this.onPointerDown);
        }

        if (this.controlsTextures) {
            this.controls = new Container();
            this.buildControls();
        }

        if (combinedFeatures.autoTransition) {
            this.timeBetweenAutoTransitionsMS = combinedFeatures.autoTransition.slideChangeTime;
        }

        if (shouldAddChildren) {
            this.addChildren();
        }
    }

    public sizeComponents(viewportWidth: number, viewportHeight: number, slideWidth: number = viewportWidth, slideHeight: number = viewportHeight, slideOffsets: PointData = { x: 0, y: 0 }): void {
        if (this.swipeRegion) {
            this.swipeRegion.width = viewportWidth;
            this.swipeRegion.height = viewportHeight;
        }

        this.slideOutPosition = viewportWidth * 2;
        this.slideInPosition = slideOffsets.x;

        this.resizeSlideMask(slideWidth, slideHeight, slideOffsets);
        this.slides.forEach((slide) => {
            slide.resize(slideWidth, slideHeight, slideOffsets);
            slide.position.x = this.slideOutPosition;
        });

        this.swipeThreshold = slideWidth * 0.15;
        if (this.slides.length > 0) {
            this.slides[this.currentSlideIndex].position.x = this.slideInPosition;
        }

        if (this.controls) {
            (this.controls.children as SliderControl[]).forEach((control) => {
                control.handleOrientationChange(viewportHeight * 0.1);
            });

            this.controls.position.x = -(this.controls.width * 0.5);
            this.controls.position.y = (viewportHeight * 0.5) - (this.controls.height * 1.2);
        }
    }

    public destroy(): void {
        this.swipeRegion?.off('pointerdown', this.onPointerDown);
        super.destroy();
    }

    protected addChildren(): void {
        this.addChild(this.slideMask);
        this.slides.forEach((slide: Slide) => {
            this.addChild(slide);
        });

        if (this.swipeRegion) { this.addChild(this.swipeRegion); }
        if (this.controls) { this.addChild(this.controls); }
    }

    protected onSlideInFinished(): void {
        this.enableInteractions();
    }

    protected transitionSlideLeft(isAutoTransition: boolean = false, goToLastSlide: boolean = false, newSlideIndex?: number): void {
        let slideIndex = newSlideIndex !== undefined ? newSlideIndex : this.currentSlideIndex === this.slides.length - 1 ? 0 : this.currentSlideIndex + 1;
        const duration = isAutoTransition ? this.autoTransitionDurationS : this.transitionDurationS;

        if (goToLastSlide) {
            slideIndex = this.slides.length - 1;
        }

        this.slides[slideIndex].position.x = this.slideOutPosition;

        this.slideOutTween = TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: -this.slideOutPosition
        });

        this.currentSlideIndex = slideIndex;
    }

    protected transitionSlideRight(isAutoTransition: boolean = false, goToFirstSlide: boolean = false, newSlideIndex?: number): void {
        let slideIndex = newSlideIndex !== undefined ? newSlideIndex : this.currentSlideIndex === 0 ? this.slides.length - 1 : this.currentSlideIndex - 1;
        const duration = isAutoTransition ? this.autoTransitionDurationS : this.transitionDurationS;

        if (goToFirstSlide) {
            slideIndex = 0;
        }

        this.slides[slideIndex].position.x = -this.slideOutPosition;

        this.slideOutTween = TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: this.slideOutPosition
        });

        this.currentSlideIndex = slideIndex;
    }

    protected transitionSlideIn(isAutoTransition: boolean = false): void {
        this.updateControls();

        const duration = isAutoTransition ? this.autoTransitionDurationS : this.transitionDurationS;
        this.recentreSlide(duration, this.onSlideInFinished.bind(this));
    }

    protected recentreSlide(duration: number, onComplete?: () => void): void {
        this.startAutoSlideTimeout();
        this.slideInTween = TweenLite.to(this.slides[this.currentSlideIndex].position, duration, {
            x: this.slideInPosition,
            onComplete
        });
    }

    protected killTransitionTweens(): void {
        this.slideInTween?.kill();
        this.slideOutTween?.kill();
    }

    protected disableInteractions(): void {
        if (this.swipeRegion) {
            this.swipeRegion.interactive = false;
        }
    }

    protected enableInteractions(): void {
        if (this.swipeRegion) {
            this.swipeRegion.interactive = true;
        }
    }

    protected resizeSlideMask(width: number, height: number, offset: { x: number, y: number }): void {
        this.slideMask.clear();
        this.slideMask.beginFill(0xffffff);
        this.slideMask.drawRect(-(width * 0.5) + offset.x, -(height * 0.5) + offset.y, width, height);
        this.slideMask.endFill();
    }

    protected startAutoSlideTimeout(): void {
        if (!this.timeBetweenAutoTransitionsMS) { return; }

        this.clearAutoSlideTimeout();
        this.autoTransitionTimeout = window.setTimeout(() => {
            this.goToNextSlide(true);
        }, this.timeBetweenAutoTransitionsMS);
    }

    protected clearAutoSlideTimeout(): void {
        if (!this.timeBetweenAutoTransitionsMS) { return; }

        window.clearTimeout(this.autoTransitionTimeout);
    }

    protected buildControls(): void {
        if (this.controlsTextures) {
            this.controls?.removeChildren();
            const textures = this.controlsTextures;
            
            this.slides.forEach((_, index) => {
                const enabled = index === this.currentSlideIndex;
                const control = new SliderControl(textures, enabled, this.goToSlideAt.bind(this), index);
                this.controls?.addChild(control);
            });
        }
    }

    protected goToNextSlide(isAutoTransition: boolean = false): void {
        this.transitionSlideLeft(isAutoTransition);
        this.transitionSlideIn(isAutoTransition);
        this.disableInteractions();
    }

    protected goToPreviousSlide(isAutoTransition: boolean = false): void {
        this.transitionSlideRight(isAutoTransition);
        this.transitionSlideIn(isAutoTransition);
        this.disableInteractions();
    }

    private goToSlideAt(slideIndex: number): void {
        if (this.currentSlideIndex === 0 && slideIndex === this.slides.length - 1) {
            if (this.slides.length > 2) {
                this.transitionSlideRight();
            } else {
                this.transitionSlideLeft();
            }
        } else if (this.currentSlideIndex === this.slides.length - 1 && slideIndex === 0) {
            if (this.slides.length > 2) {
                this.transitionSlideLeft();
            } else {
                this.transitionSlideRight();
            }
        } else if (slideIndex < this.currentSlideIndex) {
            this.transitionSlideRight(false, false, slideIndex);
        } else {
            this.transitionSlideLeft(false, false, slideIndex);
        }

        this.transitionSlideIn();
        this.disableInteractions();
    }

    private updateControls(): void {
        if (!this.controls) { return; }

        const controlsContainer = (this.controls.children as SliderControl[]);
        controlsContainer.forEach((control) => {
            control.disable();
        });

        controlsContainer[this.currentSlideIndex].enable();
    }

    private onPointerDown(e: FederatedPointerEvent): void {
        if (!this.swipeRegion) { return; }

        this.clearAutoSlideTimeout();

        this.interactionData = e;

        this.swipeRegion.on('pointerup', this.onPointerUp);
        this.swipeRegion.on('pointerout', this.onPointerUp);
        this.swipeRegion.on('pointermove', this.onPointerMove);
        this.swipeRegion.on('pointerupoutside', this.onPointerUp);

        const parent = this.slides[this.currentSlideIndex].parent;
        if (parent) {
            this.moveOffset = this.slides[this.currentSlideIndex].x - this.interactionData.getLocalPosition(parent).x;
        }
    }

    private onPointerMove(): void {
        if (!this.swipeRegion || !this.interactionData) { return; }

        const parent = this.slides[this.currentSlideIndex].parent;
        if (parent) {
            this.slides[this.currentSlideIndex].x = this.interactionData.getLocalPosition(parent).x + this.moveOffset;
        }
    }

    private onPointerUp(): void {
        if (!this.swipeRegion) { return; }

        const distance = this.slides[this.currentSlideIndex].position.x - this.slideInPosition;
        if (distance > this.swipeThreshold || distance < -this.swipeThreshold) {
            this.disableInteractions();
            if (this.slides[this.currentSlideIndex].position.x > this.slideInPosition) {
                this.transitionSlideRight();
            } else {
                this.transitionSlideLeft();
            }
            this.transitionSlideIn();
        } else {
            this.recentreSlide(this.transitionDurationS);
        }

        this.swipeRegion.off('pointermove', this.onPointerMove);
        this.swipeRegion.off('pointerup', this.onPointerUp);
        this.swipeRegion.off('pointerout', this.onPointerUp);
        this.swipeRegion.off('pointerupoutside', this.onPointerUp);

        this.interactionData = null;
    }
}
